/**
 * The shader runtime of the effects layer (ADR 0022) — OPTIONAL. Install it
 * only for `aurora` and `halo`; every CSS effect works without it.
 *
 *   // once, in a client component at the app root (or a <script> in Astro)
 *   useEffect(() => startShaders(), []);
 *
 *   <Button className={fx("aurora")}>Publish</Button>
 *
 * It finds every element carrying a shader effect's class, mounts one canvas
 * in the part the effect paints, and draws it from tokens read where that
 * part sits. When it cannot draw — no WebGL2, a lost context, before it has
 * started, on the server — the component is untouched: THE FLOOR IS THE
 * COMPONENT, and it was already finished.
 *
 * Three objects, one job each:
 *   Renderer   the one WebGL2 context for the page (browsers allow about 16),
 *              its programs, and context loss
 *   Target     one canvas in one part: geometry, token reads, paint
 *   Scheduler  discovery, observers, the frame loop, states, quality
 *
 * The page sees each target's state on the effect's root as
 * `data-fx-<name>`: `live` · `still` (reduced motion, or a frozen clock) ·
 * `floor` (not drawing) · `lost` (context lost) · `unsupported` (no WebGL2).
 * shader.css shows a canvas only when it is `live` or `still`.
 *
 * Found on an iPhone, not in headless Chromium, and the reason for two
 * choices below: iOS Safari drops a CSS border-radius clip on a canvas while
 * its layer animates, so the SHADER draws the part's rounded shape; and a
 * positioned child starts at the padding box, so the canvas steps back over
 * the border to cover the border box.
 */

import { SHADERS, VERTEX, PRELUDE, type ShaderDef, type ShaderName } from "@/lib/shader-programs";

type Values = Record<string, number | number[]>;

export type ShaderState = "floor" | "live" | "still" | "lost" | "unsupported";

export interface ShaderSettings {
  /** null follows the OS setting; true/false forces it (stories, tests). */
  reducedMotion: boolean | null;
  /** Every target shows its floor, as without WebGL. For tests and stories. */
  forceFloor: boolean;
  /** A number freezes every clock at that time: deterministic frames. */
  freezeAt: number | null;
  /** Device-pixel cap. 2 is indistinguishable from 3 at these feature sizes. */
  maxDpr: number;
}

/**
 * Where a shader effect draws, per component — keyed by the ROOT's
 * `data-slot`, with `*` for any other element (a ground).
 *
 * - `part`   the rounded box the shader draws. Default: the root.
 * - `mount`  where the canvas lives; it covers this element's border box.
 *            Default: the part. A Slider's or a Progress's FILL is drawn on
 *            a canvas in the TRACK, so a growing fill reveals a still field
 *            and its rounded end is drawn by the shader, not clipped by CSS.
 *            `"root"` mounts a halo where its part's own overflow cannot cut it.
 * - `layer`  `under` (default): above the mount's background, below its
 *            content — a label, a check glyph. `over`: above a sibling fill
 *            inside a track, inserted DIRECTLY AFTER the fill so every later
 *            sibling (the origin mark, the THUMB) still paints above it.
 *            Appended last, it covered the Slider's thumb.
 *
 * A part that does not exist leaves the root at its floor: Slider's inline
 * variant carries text on its fill, so `aurora` applies to the track variant
 * only, and the selector says so.
 */
export interface ShaderRecipe {
  part?: string;
  mount?: string;
  layer?: "under" | "over";
}

export const SHADER_RECIPES: Record<ShaderName, Record<string, ShaderRecipe>> = {
  aurora: {
    button: {},
    switch: { part: '[data-slot="track"]' },
    checkbox: { part: '[data-slot="control"]' },
    slider: {
      part: '[data-variant="track"] [data-slot="slider-fill"]',
      mount: '[data-variant="track"] [data-slot="slider-track"]',
      layer: "over",
    },
    progress: { part: '[data-slot="fill"]', mount: '[data-slot="track"]', layer: "over" },
    "*": {},
  },
  halo: {
    button: {},
    field: { part: '[data-slot="control"]', mount: "root" },
    "*": {},
  },
};

const NAMES = Object.keys(SHADERS) as ShaderName[];
const SELECTOR = NAMES.map((n) => `.fx-${n}`).join(", ");

export const settings: ShaderSettings = { reducedMotion: null, forceFloor: false, freezeAt: null, maxDpr: 2 };

// --- reading tokens ----------------------------------------------------------

let swatch: CanvasRenderingContext2D | null = null;

/**
 * A colour token resolved where `el` sits — its brand scope, its scheme — as
 * sRGB 0..1. The browser resolves light-dark(), color-mix() and oklch(); a
 * 1×1 canvas reads the result back, which is the one parser that agrees with
 * the browser on every colour syntax by construction.
 */
export function readColor(el: HTMLElement, token: string): [number, number, number] {
  if (!swatch) {
    const c = document.createElement("canvas");
    c.width = c.height = 1;
    swatch = c.getContext("2d", { willReadFrequently: true });
  }
  const prev = el.style.color;
  el.style.color = `var(${token})`;
  const css = getComputedStyle(el).color;
  el.style.color = prev;
  if (!swatch) return [0, 0, 0];
  swatch.clearRect(0, 0, 1, 1);
  swatch.fillStyle = "#000";
  swatch.fillStyle = css;
  swatch.fillRect(0, 0, 1, 1);
  const d = swatch.getImageData(0, 0, 1, 1).data;
  return [d[0]! / 255, d[1]! / 255, d[2]! / 255];
}

/** A numeric token: `2000ms` → 2 (seconds), `16px` → 16, `0.6` → 0.6. */
export function readNumber(el: Element, token: string, fallback: number): number {
  const raw = getComputedStyle(el).getPropertyValue(token).trim();
  const n = parseFloat(raw);
  if (!Number.isFinite(n)) return fallback;
  return raw.endsWith("ms") ? n / 1000 : n;
}

// --- Renderer ------------------------------------------------------------------

interface Program {
  program: WebGLProgram;
  loc: Map<string, WebGLUniformLocation | null>;
}

class Renderer {
  readonly canvas = document.createElement("canvas");
  gl: WebGL2RenderingContext | null = null;
  lost = false;
  private programs = new Map<ShaderName, Program | null>();

  constructor(private readonly onRestored: () => void) {}

  /** True when drawing is possible right now. */
  init(): boolean {
    if (this.gl) return !this.lost;
    const gl = this.canvas.getContext("webgl2", {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      powerPreference: "low-power",
    });
    if (!gl) return false;
    this.gl = gl;
    this.canvas.addEventListener("webglcontextlost", (e) => {
      e.preventDefault();
      this.lost = true;
      this.programs.clear();
    });
    this.canvas.addEventListener("webglcontextrestored", () => {
      this.lost = false;
      this.onRestored();
    });
    return true;
  }

  private program(def: ShaderDef): Program | null {
    const cached = this.programs.get(def.name);
    if (cached !== undefined) return cached;
    const gl = this.gl!;
    const compile = (type: number, src: string) => {
      const s = gl.createShader(type)!;
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) ?? "compile failed");
      return s;
    };
    let result: Program | null = null;
    try {
      const program = gl.createProgram()!;
      gl.attachShader(program, compile(gl.VERTEX_SHADER, VERTEX));
      gl.attachShader(program, compile(gl.FRAGMENT_SHADER, PRELUDE + def.fragment));
      gl.linkProgram(program);
      if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(program) ?? "link failed");
      result = { program, loc: new Map() };
    } catch (err) {
      // A program that does not compile on this GPU leaves its targets at the
      // floor. Said once, not every frame.
      console.error(`[shader] ${def.name}:`, (err as Error).message);
    }
    this.programs.set(def.name, result);
    return result;
  }

  /** Draw one target's frame into the bottom-left w×h of the shared canvas. */
  draw(def: ShaderDef, w: number, h: number, uniforms: Values): boolean {
    const gl = this.gl;
    if (!gl || this.lost) return false;
    const p = this.program(def);
    if (!p) return false;
    // Grows only, in 128px steps: resizing a canvas reallocates its buffer.
    const W = Math.max(this.canvas.width, Math.ceil(w / 128) * 128);
    const H = Math.max(this.canvas.height, Math.ceil(h / 128) * 128);
    if (W !== this.canvas.width || H !== this.canvas.height) {
      this.canvas.width = W;
      this.canvas.height = H;
    }
    gl.viewport(0, 0, w, h);
    gl.useProgram(p.program);
    for (const [name, v] of Object.entries(uniforms)) {
      if (!p.loc.has(name)) p.loc.set(name, gl.getUniformLocation(p.program, name));
      const loc = p.loc.get(name);
      if (!loc) continue;
      if (name === "u_seed") gl.uniform1ui(loc, v as number);
      else if (Array.isArray(v)) (v.length === 2 ? gl.uniform2fv : gl.uniform3fv).call(gl, loc, v);
      else gl.uniform1f(loc, v);
    }
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    return true;
  }

  dispose() {
    this.gl?.getExtension("WEBGL_lose_context")?.loseContext();
    this.gl = null;
    this.programs.clear();
  }
}

// --- Target --------------------------------------------------------------------

/** Targets larger than this (CSS px²) step down in resolution when frames get slow. */
const BIG_AREA = 40_000;

class Target {
  readonly canvas = document.createElement("canvas");
  private readonly ctx = this.canvas.getContext("2d")!;
  /** Where the canvas lives; it covers this element's border box. */
  readonly mount: HTMLElement;
  values: Values = {};
  clock: number;
  speed = 1;
  visible = true;
  dirty = true;
  /** Null until the first frame publishes one, so even "floor" is said out loud. */
  state: ShaderState | null = null;
  w = 0;
  h = 0;
  cssW = 0;
  cssH = 0;
  dpr = 1;
  /** Live-value transitions in flight on this canvas. */
  easing = 0;
  private radius = 0;
  private readonly restore: Array<() => void> = [];

  constructor(
    readonly root: HTMLElement,
    /** The rounded box the shader draws. */
    readonly part: HTMLElement,
    readonly def: ShaderDef,
    readonly recipe: ShaderRecipe,
    readonly seed: number,
    private readonly scheduler: Scheduler,
  ) {
    this.clock = def.restTime;
    this.canvas.className = `ui-fx-canvas ui-fx-canvas-${def.name}`;
    this.canvas.setAttribute("aria-hidden", "true");
    this.mount =
      recipe.mount === "root" ? root : recipe.mount ? (root.querySelector<HTMLElement>(recipe.mount) ?? part) : part;

    // The mount must contain an absolutely positioned child; an UNDER canvas
    // also needs a stacking context so z-index -1 lands above the mount's own
    // background. Both are put back on unmount.
    const style = this.mount.style;
    const hadStyle = this.mount.hasAttribute("style");
    this.restore.push(() => {
      if (!hadStyle && this.mount.getAttribute("style") === "") this.mount.removeAttribute("style");
    });
    if (getComputedStyle(this.mount).position === "static") {
      const prev = style.position;
      style.position = "relative";
      this.restore.push(() => (style.position = prev));
    }
    if (recipe.layer === "over") this.canvas.classList.add("ui-fx-canvas-over");
    else {
      const prev = style.isolation;
      style.isolation = "isolate";
      this.restore.push(() => (style.isolation = prev));
    }

    // State values (--ui-fx-on, --ui-fx-halo-strength) are read every frame
    // only while the canvas is transitioning one of them, so they follow the
    // component's own motion token. At rest a target costs no style read.
    this.canvas.addEventListener("transitionrun", (e) => {
      if (!e.propertyName.startsWith("--ui-fx-")) return;
      this.easing++;
      this.scheduler.wake();
    });
    const settle = (e: TransitionEvent) => {
      if (!e.propertyName.startsWith("--ui-fx-")) return;
      this.easing = Math.max(0, this.easing - 1);
      this.readLive();
      this.scheduler.wake();
    };
    this.canvas.addEventListener("transitionend", settle);
    this.canvas.addEventListener("transitioncancel", settle);

    if (recipe.layer === "over" && this.mount !== part && part.parentElement === this.mount) part.after(this.canvas);
    else this.mount.appendChild(this.canvas);
    this.refresh();
  }

  setState(s: ShaderState) {
    if (this.state === s) return;
    this.state = s;
    this.dirty = true;
    this.root.setAttribute(`data-fx-${this.def.name}`, s);
  }

  /** Re-read every token. Theme, scheme and class changes call this. */
  refresh() {
    for (const [name, spec] of Object.entries(this.def.uniforms)) {
      this.values[name] =
        "color" in spec ? readColor(this.canvas, spec.color) : readNumber(this.canvas, spec.number, spec.fallback ?? 0);
    }
    this.speed = readNumber(this.canvas, "--ui-fx-ambient-speed", 1);
    this.layout();
  }

  readLive() {
    for (const [name, spec] of Object.entries(this.def.uniforms)) {
      if (!("live" in spec) || !spec.live) continue;
      const v = readNumber(this.canvas, spec.number, spec.fallback ?? 0);
      if (v !== this.values[name]) {
        this.values[name] = v;
        this.dirty = true;
      }
    }
  }

  layout(quality = this.scheduler.quality) {
    const bleed = this.def.bleed ?? 0;
    const m = this.mount;
    // LAYOUT size, not the transformed box: a pressed Button is scaled by
    // --ui-press-scale and its canvas scales with it.
    this.cssW = m.offsetWidth + 2 * bleed;
    this.cssH = m.offsetHeight + 2 * bleed;
    const s = this.canvas.style;
    // An absolutely positioned child is placed from the PADDING box; the
    // canvas covers the BORDER box, so it steps back over the border.
    s.left = `${-m.clientLeft - bleed}px`;
    s.top = `${-m.clientTop - bleed}px`;
    s.width = `${this.cssW}px`;
    s.height = `${this.cssH}px`;
    const big = this.cssW * this.cssH > BIG_AREA;
    this.dpr = Math.min(devicePixelRatio || 1, settings.maxDpr) * (big ? quality : 1);
    const w = Math.max(1, Math.round(this.cssW * this.dpr));
    const h = Math.max(1, Math.round(this.cssH * this.dpr));
    if (w !== this.canvas.width || h !== this.canvas.height) {
      this.canvas.width = this.w = w;
      this.canvas.height = this.h = h;
    }
    this.values.u_bleed = bleed;
    this.radius = parseFloat(getComputedStyle(this.part).borderTopLeftRadius) || 0;
    this.measureShape();
    this.dirty = true;
  }

  /**
   * The shape's box in canvas CSS px, y up (GL). Measured every frame for a
   * shape that moves inside its mount: a Progress fill growing through its
   * transition, a Slider fill under the pointer.
   */
  measureShape() {
    const bleed = this.def.bleed ?? 0;
    let x = 0;
    let y = 0;
    let w = this.mount.offsetWidth;
    let h = this.mount.offsetHeight;
    if (this.part !== this.mount) {
      const mr = this.mount.getBoundingClientRect();
      const k = mr.width / (this.mount.offsetWidth || 1) || 1;
      const r = this.part.getBoundingClientRect();
      x = (r.left - mr.left) / k;
      y = (r.top - mr.top) / k;
      w = r.width / k;
      h = r.height / k;
    }
    const center = [bleed + x + w / 2, this.cssH - (bleed + y + h / 2)];
    const box = [w / 2, h / 2];
    const prev = this.values.u_center as number[] | undefined;
    const prevBox = this.values.u_box as number[] | undefined;
    if (prev?.[0] === center[0] && prev?.[1] === center[1] && prevBox?.[0] === box[0] && prevBox?.[1] === box[1]) return;
    this.values.u_center = center;
    this.values.u_box = box;
    this.values.u_radius = Math.min(this.radius, w / 2, h / 2);
    this.dirty = true;
  }

  paint(renderer: Renderer): boolean {
    const uniforms: Values = {
      ...this.values,
      u_resolution: [this.w, this.h],
      u_time: this.clock,
      u_dpr: this.dpr,
      u_seed: this.seed,
    };
    if (!renderer.draw(this.def, this.w, this.h, uniforms)) return false;
    this.ctx.globalCompositeOperation = "copy";
    // GL rows start at the bottom: the drawn region is the bottom-left corner.
    this.ctx.drawImage(renderer.canvas, 0, renderer.canvas.height - this.h, this.w, this.h, 0, 0, this.w, this.h);
    this.ctx.globalCompositeOperation = "source-over";
    this.dirty = false;
    return true;
  }

  /** The last frame's pixels, premultiplied. What a contrast test samples. */
  pixels(): ImageData {
    return this.ctx.getImageData(0, 0, this.w, this.h);
  }

  unmount() {
    this.canvas.remove();
    this.root.removeAttribute(`data-fx-${this.def.name}`);
    // Last in, first out: the attribute check runs after the values are back.
    for (const undo of this.restore.splice(0).reverse()) undo();
  }
}

// --- Scheduler ----------------------------------------------------------------

class Scheduler {
  readonly renderer: Renderer;
  readonly targets = new Set<Target>();
  quality = 1;
  private byRoot = new WeakMap<HTMLElement, Map<ShaderName, Target>>();
  private byMount = new Map<Element, Set<Target>>();
  private seed = 1;
  private raf = 0;
  private last = 0;
  private frames = 0;
  private spent = 0;
  private since = 0;
  private refreshQueued = false;
  /** Set by stop(). A font load or a queued refresh still in flight must not
   *  resurrect canvases into the next page — found by the refcount test. */
  private stopped = false;
  private pending = new Set<Element>();
  private readonly teardown: Array<() => void> = [];
  private readonly reducedMotion = matchMedia("(prefers-reduced-motion: reduce)");

  private intersection = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        for (const t of this.byMount.get(e.target) ?? []) {
          t.visible = e.isIntersecting;
          if (t.visible) t.dirty = true;
        }
      }
      this.wake();
    },
    { rootMargin: "160px" },
  );

  private resize = new ResizeObserver((entries) => {
    for (const e of entries) {
      for (const t of this.targets) if (t.mount === e.target || t.part === e.target) t.layout();
    }
    this.wake();
  });

  constructor() {
    this.renderer = new Renderer(() => {
      for (const t of this.targets) t.dirty = true;
      this.wake();
    });
  }

  private isStill() {
    return settings.freezeAt !== null || (settings.reducedMotion ?? this.reducedMotion.matches);
  }

  start() {
    this.sweep();

    // The runtime writes styles on its own canvases and mounts and appends
    // canvases: those mutations must not schedule another read.
    const ours = (n: Node) => n instanceof HTMLCanvasElement && n.classList.contains("ui-fx-canvas");
    const observer = new MutationObserver((records) => {
      let added = false;
      for (const r of records) {
        if (r.type === "childList") {
          if (![...r.addedNodes, ...r.removedNodes].every(ours)) added = true;
          continue;
        }
        if (ours(r.target)) continue;
        // Geometry is the observers' business: a Slider fill's inline width
        // changes on every pointer move, and re-reading tokens for it would
        // cost a style read per uniform per frame of a drag. But an inline
        // TOKEN on the same element — `style={{ "--ui-fx-aurora-intensity":
        // 0.5 }}` on a Button — is a token change like any other.
        if (r.attributeName === "style" && this.geometry(r.target as Element)) {
          const tokens = (css: string | null) => (css?.match(/--[\w-]+\s*:[^;]*/g) ?? []).join(";");
          if (tokens(r.oldValue) === tokens((r.target as Element).getAttribute("style"))) continue;
        }
        this.pending.add(r.target as Element);
      }
      if (added || this.pending.size) this.queueRefresh(added);
    });
    observer.observe(document.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeOldValue: true,
      // What can change a token or an effect class: a class, an inline style,
      // and the attributes the token emitter scopes brands and schemes with.
      attributeFilter: ["class", "style", "data-ui-theme", "data-theme", "data-scheme", "data-color-scheme"],
    });
    this.teardown.push(() => observer.disconnect());

    const all = () => {
      this.pending.add(document.documentElement);
      this.queueRefresh(false);
    };
    const scheme = matchMedia("(prefers-color-scheme: dark)");
    scheme.addEventListener("change", all);
    this.reducedMotion.addEventListener("change", all);
    this.teardown.push(() => {
      scheme.removeEventListener("change", all);
      this.reducedMotion.removeEventListener("change", all);
    });
    void document.fonts?.ready.then(() => this.targets.size && all());
    this.wake();
  }

  stop() {
    this.stopped = true;
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    for (const undo of this.teardown.splice(0)) undo();
    this.intersection.disconnect();
    this.resize.disconnect();
    for (const t of this.targets) t.unmount();
    this.targets.clear();
    this.byMount.clear();
    this.byRoot = new WeakMap();
    this.renderer.dispose();
  }

  /** Is `el` a part or a mount — something the runtime measures rather than reads? */
  private geometry(el: Element) {
    if (this.byMount.has(el)) return true;
    for (const t of this.targets) if (t.part === el) return true;
    return false;
  }

  private attach(root: HTMLElement) {
    let mine = this.byRoot.get(root);
    if (!mine) this.byRoot.set(root, (mine = new Map()));
    for (const name of NAMES) {
      if (!root.classList.contains(`fx-${name}`) || mine.has(name)) continue;
      const recipes = SHADER_RECIPES[name];
      const slot = root.dataset.slot;
      const recipe = (slot ? recipes[slot] : undefined) ?? recipes["*"]!;
      const part = recipe.part ? root.querySelector<HTMLElement>(recipe.part) : root;
      if (!part) continue;
      const t = new Target(root, part, SHADERS[name], recipe, this.seed++, this);
      mine.set(name, t);
      this.targets.add(t);
      let set = this.byMount.get(t.mount);
      if (!set) this.byMount.set(t.mount, (set = new Set()));
      set.add(t);
      this.intersection.observe(t.mount);
      this.resize.observe(t.mount);
      if (t.mount !== part) this.resize.observe(part);
    }
  }

  private detach(t: Target) {
    t.unmount();
    this.targets.delete(t);
    this.byRoot.get(t.root)?.delete(t.def.name);
    const set = this.byMount.get(t.mount);
    set?.delete(t);
    if (set && !set.size) {
      this.byMount.delete(t.mount);
      this.intersection.unobserve(t.mount);
      this.resize.unobserve(t.mount);
    }
  }

  private sweep() {
    for (const t of [...this.targets]) {
      const stillThere = t.root.isConnected && t.part.isConnected && t.root.classList.contains(`fx-${t.def.name}`);
      if (!stillThere) this.detach(t);
    }
    for (const el of document.querySelectorAll<HTMLElement>(SELECTOR)) this.attach(el);
  }

  /**
   * Batched to the next frame. A changed element re-reads only the targets
   * it can reach: its own subtree, or an ancestor's (a class on <html> moves
   * every token beneath it). Typing in a field re-reads nothing.
   */
  private queueRefresh(sweep: boolean) {
    if (this.stopped) return;
    if (sweep) this.pending.add(document.documentElement);
    if (this.refreshQueued) return;
    this.refreshQueued = true;
    requestAnimationFrame(() => {
      this.refreshQueued = false;
      if (this.stopped) return;
      const changed = [...this.pending];
      this.pending.clear();
      this.sweep();
      for (const t of this.targets) {
        if (changed.some((el) => el.contains(t.root) || t.root.contains(el))) t.refresh();
      }
      this.wake();
    });
  }

  /** Schedule a frame if none is pending. The loop sleeps while nothing moves. */
  wake() {
    if (this.stopped || this.raf || !this.targets.size) return;
    this.raf = requestAnimationFrame((now) => this.frame(now));
  }

  private frame(now: number) {
    this.raf = 0;
    const dt = this.last ? Math.min(0.1, (now - this.last) / 1000) : 0;
    this.last = now;
    const t0 = performance.now();
    const still = this.isStill();
    const usable = !settings.forceFloor && this.renderer.init();
    const offState: ShaderState = settings.forceFloor
      ? "floor"
      : this.renderer.lost
        ? "lost"
        : this.renderer.gl
          ? "floor"
          : "unsupported";
    let moving = false;
    for (const t of this.targets) {
      if (!usable) {
        t.setState(offState);
        continue;
      }
      t.setState(still ? "still" : "live");
      if (!t.visible) continue;
      if (t.easing) {
        t.readLive();
        moving = true;
      }
      if (t.part !== t.mount) t.measureShape();
      if (t.def.idle?.(t.values) && !t.dirty) continue;
      if (still) {
        const at = settings.freezeAt ?? t.def.restTime;
        if (t.clock !== at) {
          t.clock = at;
          t.dirty = true;
        }
        if (t.dirty) t.paint(this.renderer);
        continue;
      }
      t.clock += dt * t.speed;
      t.paint(this.renderer);
      moving = true;
    }
    this.measure(now, performance.now() - t0);
    // The loop sleeps once nothing moves: still targets are drawn once, an
    // idle halo not at all. Anything that changes a target — a transition on
    // the canvas, a resize, a token, visibility — wakes it again. With no
    // usable context there is nothing to wake for until it comes back.
    if (usable && (moving || [...this.targets].some((t) => t.dirty && t.visible))) this.wake();
    else this.last = 0;
  }

  /**
   * Adaptive quality. Full device resolution by default. Only when frames
   * get slow do LARGE targets step down, a quarter at a time, and step back
   * up once there is room. Small controls always render at full resolution.
   */
  private measure(now: number, ms: number) {
    if (!this.since) this.since = now;
    this.spent += ms;
    this.frames++;
    if (now - this.since < 500) return;
    const per = this.spent / this.frames;
    this.frames = 0;
    this.spent = 0;
    this.since = now;
    const next = per > 12 ? Math.max(0.5, this.quality - 0.25) : per < 5 ? Math.min(1, this.quality + 0.25) : this.quality;
    if (next === this.quality) return;
    this.quality = next;
    for (const t of this.targets) if (t.cssW * t.cssH > BIG_AREA) t.layout(next);
  }

  /** Draw a target now and read its pixels back. */
  sample(root: HTMLElement, name: ShaderName) {
    const t = this.byRoot.get(root)?.get(name);
    if (!t || !t.paint(this.renderer)) return null;
    const { data } = t.pixels();
    return { data, width: t.w, height: t.h, dpr: t.dpr };
  }
}

// --- public API --------------------------------------------------------------

let scheduler: Scheduler | null = null;
let starts = 0;

/**
 * Start the runtime and return its stop function. Safe to call on the
 * server (it does nothing there) and more than once: it counts its callers
 * and stops when the last one has, so React's StrictMode double effect, or
 * two islands that each start it, share one runtime.
 */
export function startShaders(): () => void {
  if (typeof window === "undefined" || typeof document === "undefined") return () => {};
  if (typeof IntersectionObserver === "undefined" || typeof ResizeObserver === "undefined") return () => {};
  starts++;
  if (!scheduler) {
    scheduler = new Scheduler();
    scheduler.start();
  }
  let stopped = false;
  return () => {
    if (stopped) return;
    stopped = true;
    if (--starts > 0 || !scheduler) return;
    scheduler.stop();
    scheduler = null;
  };
}

/** Override what the runtime would detect — for stories, tests and screenshots. */
export function configureShaders(next: Partial<ShaderSettings>): void {
  Object.assign(settings, next);
  if (!scheduler) return;
  for (const t of scheduler.targets) {
    t.dirty = true;
    t.layout();
  }
  scheduler.wake();
}

/**
 * Draw the effect on `root` now and return its pixels (premultiplied RGBA,
 * device px), or null if it is not drawing. What a contrast test samples:
 * the guard is only as good as the measurement that holds it.
 */
export function sampleShader(root: HTMLElement, name: ShaderName) {
  return scheduler?.sample(root, name) ?? null;
}

/**
 * The shader programs of the effects layer (ADR 0022): aurora and halo, and
 * the GLSL they share. Paired with `@/lib/shader`, which runs them.
 *
 * THE ADMISSION RULE, which `pnpm check:fx` enforces on this file:
 *
 *   1. A shader paints only pixels it owns — its part's fill, or a ground.
 *      It never reads the page, a backdrop or another canvas: no sampler2D,
 *      no texture(). (Refraction failed exactly here, twice.)
 *   2. Every input is a token, read where the part sits: every uniform below
 *      names a `--…` custom property.
 *   3. Its floor is the component. Nothing here draws what the component
 *      does not already show; it only paints over a fill that exists.
 *   4. It guards the contrast of the ink its part carries, per pixel
 *      (`fx_guard`), and the browser test samples the result.
 *
 * The GLSL prelude — hashing, noise, OKLab, the guard, the shape — is kept
 * as measured in the effects lab. Hash: lowbias32 by Chris Wellons (public
 * domain). OKLab: Björn Ottosson's published matrices (public domain).
 */

import type { ShaderFxName } from "@/lib/fx";

export type ShaderName = ShaderFxName;

/** A uniform's source: a colour token, or a numeric one. `live` ones follow a CSS transition. */
export type UniformSpec = { color: string } | { number: string; fallback?: number; live?: boolean };

export interface ShaderDef {
  name: ShaderName;
  fragment: string;
  /** Every uniform names a token (rule 2). */
  uniforms: Record<string, UniformSpec>;
  /** The frame shown under reduced motion: chosen, not t = 0. */
  restTime: number;
  /** CSS px the canvas reaches past its part, for a light that falls off. */
  bleed?: number;
  /** Skip drawing while this holds (a halo faded to nothing costs nothing). */
  idle?: (values: Record<string, number | number[]>) => boolean;
}

export const VERTEX = `#version 300 es
// One triangle that covers the viewport: (-1,-1) (3,-1) (-1,3). No buffers.
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

// highp on purpose: mediump float is fp16 on many phone GPUs (noise turns to
// blocks past ~2048) and mediump int is 16-bit (every integer hash breaks).
// Desktop GPUs run mediump as highp, so the bug hides where shaders are written.
export const PRELUDE = `#version 300 es
precision highp float;
precision highp int;

uniform vec2  u_resolution;  // drawing size, device px
uniform float u_time;        // seconds, scaled by the motion knob
uniform float u_dpr;
uniform uint  u_seed;
out vec4 fragColor;

// lowbias32 (Chris Wellons, public domain): integer hashing, stable across GPUs.
uint fx_hash(uint x) {
  x ^= x >> 16; x *= 0x7feb352du; x ^= x >> 15; x *= 0x846ca68bu; x ^= x >> 16; return x;
}
uint fx_hash(uvec3 v) { return fx_hash(v.x ^ fx_hash(v.y ^ fx_hash(v.z ^ u_seed))); }
float fx_rand(uvec3 v) { return float(fx_hash(v)) * (1.0 / 4294967295.0); }

vec2 fx_grad(ivec2 c, uint salt) {
  float a = fx_rand(uvec3(uvec2(c + 65536), salt)) * 6.2831853;
  return vec2(cos(a), sin(a));
}
float fx_noise(vec2 p, uint salt) {
  ivec2 i = ivec2(floor(p)); vec2 f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  float a = dot(fx_grad(i, salt), f);
  float b = dot(fx_grad(i + ivec2(1, 0), salt), f - vec2(1.0, 0.0));
  float c = dot(fx_grad(i + ivec2(0, 1), salt), f - vec2(0.0, 1.0));
  float d = dot(fx_grad(i + ivec2(1, 1), salt), f - vec2(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fx_fbm(vec2 p, uint salt) {
  float sum = 0.0, amp = 0.5;
  for (int o = 0; o < 4; o++) { sum += amp * fx_noise(p, salt + uint(o)); p = mat2(1.6, 1.2, -1.2, 1.6) * p; amp *= 0.5; }
  return sum;
}

// sRGB <-> OKLab (Bjorn Ottosson's published matrices).
vec3 fx_toLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }
vec3 fx_toSrgb(vec3 c) { c = clamp(c, 0.0, 1.0); return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c)); }
vec3 fx_oklab(vec3 srgb) {
  vec3 c = fx_toLinear(srgb);
  float l = pow(max(0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b, 0.0), 1.0 / 3.0);
  float m = pow(max(0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b, 0.0), 1.0 / 3.0);
  float s = pow(max(0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b, 0.0), 1.0 / 3.0);
  return vec3(0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
              1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
              0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
}
vec3 fx_srgb(vec3 lab) {
  float l = lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z;
  float m = lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z;
  float s = lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z;
  l = l * l * l; m = m * m * m; s = s * s * s;
  return fx_toSrgb(vec3(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
                       -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
                       -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s));
}
vec3 fx_hueTurn(vec3 lab, float r) { float c = cos(r), s = sin(r); return vec3(lab.x, c * lab.y - s * lab.z, s * lab.y + c * lab.z); }
float fx_luma(vec3 lin) { return dot(lin, vec3(0.2126, 0.7152, 0.0722)); }

// Soft limit: identity below 75% of 'lim', then eases toward 'lim' and never
// reaches it. Continuous slope at the knee, so a gradient that runs into the
// limit bends instead of flattening into a plateau with a visible edge.
float fx_softLimit(float y, float lim) {
  float k = 0.75 * lim;
  if (y <= k) return y;
  float r = max(lim - k, 1e-5);
  return k + r * (1.0 - exp(-(y - k) / r));
}

// The contrast guard. Keeps 'color' at least 'ratio' away from 'avoid', on
// the side where 'side' lies (lighter or darker). Contrast is a ratio of
// luminances and scaling linear RGB scales luminance exactly, so the pixel
// moves in one step. 2% margin covers 8-bit rounding. ratio 0 = off.
vec3 fx_guard(vec3 color, vec3 avoid, vec3 side, float ratio) {
  if (ratio <= 0.0) return color;
  float target = ratio * 1.02;
  vec3 lin = fx_toLinear(clamp(color, 0.0, 1.0));
  float y = fx_luma(lin);
  float ay = fx_luma(fx_toLinear(avoid));
  if (ay > fx_luma(fx_toLinear(side))) {
    float maxY = max((ay + 0.05) / target - 0.05, 0.0);
    float want = fx_softLimit(y, maxY);
    if (want < y) {
      // Darken in OKLab, KEEPING chroma: scaling linear RGB alone would grey
      // the light out exactly where the guard works hardest (a dark ground).
      // Then rescale to the exact luminance the limit allows.
      vec3 lab = fx_oklab(fx_toSrgb(lin));
      lab.x *= pow(want / max(y, 1e-5), 1.0 / 3.0);
      lin = fx_toLinear(fx_srgb(lab));
      lin *= want / max(fx_luma(lin), 1e-5);
    }
  } else {
    float minY = min(target * (ay + 0.05) - 0.05, 1.0);
    float want = 1.0 - fx_softLimit(1.0 - y, 1.0 - minY);
    if (want > y) lin = mix(lin, vec3(1.0), (want - y) / max(1.0 - y, 1e-4));
  }
  return fx_toSrgb(lin);
}

float fx_roundBox(vec2 p, vec2 halfSize, float r) {
  vec2 q = abs(p) - halfSize + r;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r;
}

// The shape: the part's own rounded box, in canvas CSS px (y up). The shader
// draws it, antialiased to one device pixel, so nothing depends on CSS
// clipping a canvas (which iOS Safari drops while a layer animates).
uniform vec2  u_center;
uniform vec2  u_box;
uniform float u_radius;
float fx_shapeDistance(vec2 css) { return fx_roundBox(css - u_center, u_box, u_radius); }
float fx_cover(float d) { return clamp(0.5 - d * u_dpr, 0.0, 1.0); }
`;

/**
 * The aurora field. Light gathers in RIBBONS along two level lines of a
 * slowly folding noise field: crisp at the core, falling off over a long,
 * smooth tail. A broad haze sits under them so the light never stops
 * abruptly.
 */
const FIELD = `
vec2 fx_auroraMasks(vec2 p, float t) {
  vec2 warp = vec2(fx_fbm(0.8 * p + vec2(0.0, t), 11u), fx_fbm(0.8 * p + vec2(5.2, -t), 12u));
  vec2 q = p + 1.4 * warp;
  float f = fx_fbm(q + vec2(0.5 * t, 0.0), 13u);
  float g = fx_fbm(0.6 * q + vec2(7.0, -0.4 * t), 14u);
  float x1 = abs(f - 0.04);
  float x2 = abs(g + 0.03);
  float r1 = exp(-pow(x1 / 0.032, 2.0)) * 0.7 + exp(-x1 / 0.13) * 0.45;
  float r2 = exp(-pow(x2 / 0.045, 2.0)) * 0.6 + exp(-x2 / 0.16) * 0.4;
  float haze = smoothstep(-0.4, 0.5, f) * 0.22;
  float m1 = clamp(r1 + haze, 0.0, 1.0);
  return vec2(m1, clamp(r2, 0.0, 1.0) * (1.0 - 0.55 * r1));
}`;

export const SHADERS: Record<ShaderName, ShaderDef> = {
  aurora: {
    name: "aurora",
    restTime: 6,
    uniforms: {
      u_base: { color: "--ui-fx-aurora-base" },
      u_light: { color: "--ui-fx-aurora-light" },
      u_avoid: { color: "--ui-fx-aurora-guard-ink" },
      u_guard: { number: "--ui-fx-aurora-guard", fallback: 4.5 },
      u_intensity: { number: "--ui-fx-aurora-intensity", fallback: 0.7 },
      u_scale: { number: "--ui-fx-aurora-scale", fallback: 420 },
      u_grain: { number: "--ui-fx-grain-amount", fallback: 0 },
      u_dissolve: { number: "--ui-fx-aurora-dissolve", fallback: 0 },
      u_on: { number: "--ui-fx-on", fallback: 1, live: true },
    },
    idle: (v) => (v.u_on as number) <= 0.001,
    fragment: `
uniform vec3 u_base;      // the fill the effect replaces
uniform vec3 u_light;     // the brand light moving through it
uniform vec3 u_avoid;     // the ink that sits on it (guarded against)
uniform float u_guard;    // the contrast that ink keeps
uniform float u_intensity;
uniform float u_scale;    // feature size, CSS px
uniform float u_grain;
uniform float u_dissolve; // 0 = fill to the edge; >0 = fraction of the shape the light fades over
uniform float u_on;       // 0..1, follows the component's own state transition
${FIELD}
void main() {
  vec2 css = gl_FragCoord.xy / u_dpr;
  float d = fx_shapeDistance(css);
  vec2 m = fx_auroraMasks(css / u_scale, u_time * 0.05);
  // Dissolve: the light thins out toward the shape's edge, so a ground melts
  // into the page around it instead of ending at its border.
  float reach = u_dissolve * 2.0 * min(u_box.x, u_box.y);
  float fade = u_dissolve > 0.0 ? smoothstep(0.0, 1.0, clamp(-d / max(reach, 1.0), 0.0, 1.0)) : 1.0;
  vec3 base = fx_oklab(u_base);
  vec3 light = fx_oklab(u_light);
  vec3 lab = mix(base, light, m.x * u_intensity * fade);
  lab = mix(lab, fx_hueTurn(light, radians(55.0)), m.y * u_intensity * 0.8 * fade);
  vec3 rgb = fx_srgb(lab);
  // Static: grain that changes every frame reads as flicker, not texture.
  float n = fx_rand(uvec3(uvec2(gl_FragCoord.xy), 0u)) - 0.5;
  rgb += n * (1.5 / 255.0 + u_grain);
  rgb = fx_guard(rgb, u_avoid, u_base, u_guard);
  float a = fx_cover(d) * u_on;
  fragColor = vec4(rgb * a, a);
}`,
  },

  halo: {
    name: "halo",
    restTime: 2.2,
    bleed: 22,
    uniforms: {
      u_light: { color: "--ui-fx-halo-light" },
      u_ground: { color: "--ui-bg-base" },
      u_strength: { number: "--ui-fx-halo-strength", fallback: 0, live: true },
      u_loop: { number: "--ui-duration-loop", fallback: 2 },
    },
    idle: (v) => (v.u_strength as number) <= 0.001,
    fragment: `
uniform vec3 u_light;
uniform vec3 u_ground;
uniform float u_strength;  // 0..1, follows a CSS transition
uniform float u_loop;      // --ui-duration-loop, seconds: the light laps once per loop
uniform float u_bleed;
void main() {
  vec2 p = gl_FragCoord.xy / u_dpr - u_center;
  float d = fx_shapeDistance(gl_FragCoord.xy / u_dpr);
  float angle = atan(p.y * (u_box.x / max(u_box.y, 1.0)), p.x);
  vec2 ring = vec2(cos(angle), sin(angle));     // seamless round the edge
  float t = u_time * 0.35;
  float flow = fx_noise(ring * 1.8 + vec2(t, -0.7 * t), 21u) * 0.9 + 0.5;
  // One lap per --ui-duration-loop: a working button and its shimmering
  // status line keep one rhythm.
  float comet = pow(0.5 + 0.5 * cos(angle - u_time * 6.2831853 / max(u_loop, 0.1)), 10.0);
  float energy = clamp(0.3 + flow * 0.6 + comet * 0.9, 0.0, 1.6);
  float outside = max(d, 0.0);
  // No crisp edge line: a sharp ring would read as the focus indicator.
  float glow = exp(-outside / (0.26 * u_bleed));
  float alpha = 0.5 * glow * energy * u_strength * smoothstep(-1.0, 1.0, d);
  vec3 light = fx_oklab(u_light);
  // A small drift only: a wide hue turn sends a green brand's halo to yellow.
  vec3 lab = mix(light, fx_hueTurn(light, radians(-18.0)), 0.5 + 0.5 * sin(angle + t));
  lab.x += fx_oklab(u_ground).x > 0.6 ? -0.06 * comet : 0.05 * comet;
  float a = clamp(alpha, 0.0, 1.0);
  fragColor = vec4(fx_srgb(lab) * a, a);
}`,
  },
};

/*
 * The shader effects' CSS (ADR 0022) — what aurora and halo are made of per
 * component, and how their canvases sit and change state. Import after
 * fx/fx.css; the runtime is `startShaders()` from `@/lib/shader`.
 *
 * WHEN an aurora is on and WHEN a halo is lit is CSS's business, not the
 * runtime's: `--ui-fx-on` and `--ui-fx-halo-strength` are registered
 * properties the canvas inherits and EASES with the component's own motion
 * tokens, and the runtime reads them only while they transition. So a
 * Switch's light follows its fill on motionMicro, and a busy Button's halo
 * comes in on `--ui-duration-enter`, without either knowing about the other.
 */

@property --ui-fx-on { syntax: "<number>"; inherits: true; initial-value: 1; }
@property --ui-fx-halo-strength { syntax: "<number>"; inherits: true; initial-value: 0; }

@layer fx {
  /* ------------------------------------------------------------ canvases */

  /* UNDER (default): above the mount's own background, below its content —
     the runtime makes the mount a stacking context for this. OVER: a sibling
     placed directly after a fill inside a track, so later siblings (a
     Slider's thumb) still paint above it.
     Hidden until the first frame: the part's own fill is the floor. The
     shader draws the part's rounded shape itself, so nothing here clips the
     canvas — iOS Safari drops a CSS clip on a canvas while its layer
     animates, which showed as square corners in every transition. */
  .ui-fx-canvas {
    position: absolute;
    display: block;
    pointer-events: none;
    z-index: -1;
    opacity: 0;
    /* Timing by USAGE (transitions.dev polish rules, mapped onto tokens):
       - the reveal over the floor is a content reveal: enter on smooth-out,
         which is exactly --ui-ease-spring;
       - --ui-fx-on follows the control's own fill (motionMicro), so light
         and fill change together;
       - a halo going out is a close: faster and quieter than coming in. */
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-on var(--ui-duration-fast) var(--ui-ease-out),
      --ui-fx-halo-strength var(--ui-duration-base) var(--ui-ease-out);
  }
  .ui-fx-canvas-over {
    z-index: auto;
  }
  /* Forced colours: the system draws the UI; no canvas at all. */
  @media (forced-colors: active) {
    .ui-fx-canvas {
      display: none;
    }
  }
  :is([data-fx-aurora="live"], [data-fx-aurora="still"]) .ui-fx-canvas-aurora,
  :is([data-fx-halo="live"], [data-fx-halo="still"]) .ui-fx-canvas-halo {
    opacity: 1;
  }

  /* -------------------------------------------------------------- aurora */

  /* A control's light follows its state: on only while checked, never while
     disabled. `data-disabled`, not `aria-disabled`: a busy Button sets
     aria-disabled (ADR 0021 — activation is unavailable) but is not drawn
     disabled, and its fill keeps moving while it works. */
  .fx-aurora:is([data-slot="switch"], [data-slot="checkbox"]):not(:has(input:checked)),
  .fx-aurora:is([data-disabled], :has(input:disabled)) {
    --ui-fx-on: 0;
  }

  /* What each part's aurora is made of, and the ink it keeps contrast with.
     A GROUND guards the WEAKEST ink placed on it (an empty state's muted
     description measured 3.6:1 in dark when the ground guarded secondary). */
  .fx-aurora {
    --ui-fx-aurora-base: var(--ui-bg-base);
    --ui-fx-aurora-light: var(--ui-bg-accent);
    --ui-fx-aurora-guard-ink: var(--ui-text-muted);
    --ui-fx-aurora-guard: 4.5;
    --ui-fx-aurora-intensity: 0.7;
    --ui-fx-aurora-scale: 420px;
  }
  /* A ground (an unslotted surface) dissolves toward its edges into the page
     around it; a component's fill runs to its edge. */
  .fx-aurora:not([data-slot]) {
    --ui-fx-aurora-dissolve: 0.22;
  }
  .fx-aurora[data-slot="button"] {
    /* The label sits on it: 4.5:1 with the on-accent ink. */
    --ui-fx-aurora-base: var(--ui-bg-accent);
    --ui-fx-aurora-light: var(--ui-bg-accent);
    --ui-fx-aurora-guard-ink: var(--ui-text-on-accent);
    --ui-fx-aurora-scale: 56px;
    --ui-fx-aurora-intensity: 1;
  }
  .fx-aurora[data-slot="switch"] {
    /* The ON track is the state (SC 1.4.11): 3:1 against the page. */
    --ui-fx-aurora-base: var(--ui-bg-accent-legible);
    --ui-fx-aurora-light: var(--ui-bg-accent-legible);
    --ui-fx-aurora-guard-ink: var(--ui-bg-base);
    --ui-fx-aurora-guard: 3;
    --ui-fx-aurora-scale: 28px;
    --ui-fx-aurora-intensity: 1;
  }
  .fx-aurora[data-slot="checkbox"] {
    /* The check glyph sits on it: 3:1, a graphic. */
    --ui-fx-aurora-base: var(--ui-bg-accent);
    --ui-fx-aurora-light: var(--ui-bg-accent);
    --ui-fx-aurora-guard-ink: var(--ui-text-on-accent);
    --ui-fx-aurora-guard: 3;
    --ui-fx-aurora-scale: 18px;
    --ui-fx-aurora-intensity: 1;
  }
  .fx-aurora[data-slot="slider"] {
    /* The thumb's ring carries SC 1.4.11 on a Slider; the fill is a
       secondary cue (slider.tsx says so), so it needs no guard. */
    --ui-fx-aurora-base: var(--ui-bg-accent);
    --ui-fx-aurora-light: var(--ui-bg-accent);
    --ui-fx-aurora-guard: 0;
    --ui-fx-aurora-scale: 90px;
    --ui-fx-aurora-intensity: 1;
  }
  .fx-aurora[data-slot="progress"] {
    /* The fill IS the value: 3:1 against its track. */
    --ui-fx-aurora-base: var(--ui-bg-accent-legible);
    --ui-fx-aurora-light: var(--ui-bg-accent-legible);
    --ui-fx-aurora-guard-ink: var(--ui-bg-sunken);
    --ui-fx-aurora-guard: 3;
    --ui-fx-aurora-scale: 90px;
    --ui-fx-aurora-intensity: 1;
  }

  /* ---------------------------------------------------------------- halo */

  /* Lit while the surface works (aria-busy) or listens (focus within a
     field). `data-fx-active` lights it by hand — a field listening for voice
     — and is searched INSIDE too, because a form control sends native props
     to its <input>, not to the root that carries the class. */
  .fx-halo {
    --ui-fx-halo-light: var(--ui-border-focus);
    --ui-fx-halo-strength: 0;
  }
  .fx-halo:is([aria-busy="true"], [data-fx-active], :has([data-fx-active])),
  .fx-halo[data-slot="field"]:focus-within {
    --ui-fx-halo-strength: 1;
  }
  /* In while work starts: an emphasis open, enter on smooth-out. On a field
     it comes in on focus — every Tab press — so quicker, and its exit is
     quicker still. Never delay an exit. */
  .fx-halo:is([aria-busy="true"], [data-fx-active], :has([data-fx-active])) .ui-fx-canvas-halo {
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-halo-strength var(--ui-duration-enter) var(--ui-ease-spring);
  }
  .fx-halo[data-slot="field"] .ui-fx-canvas-halo {
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-halo-strength var(--ui-duration-fast) var(--ui-ease-out);
  }
  .fx-halo[data-slot="field"]:focus-within .ui-fx-canvas-halo {
    transition:
      opacity var(--ui-duration-enter) var(--ui-ease-spring),
      --ui-fx-halo-strength var(--ui-duration-base) var(--ui-ease-spring);
  }
  /* The floor where the shader is not drawing: a still, soft glow. Never a
     crisp ring, which would read as the focus indicator. */
  .fx-halo[data-slot="button"]:is([aria-busy="true"], [data-fx-active]):not([data-fx-halo="live"], [data-fx-halo="still"]) {
    --tw-shadow: 0 0 18px -2px color-mix(in oklab, var(--ui-fx-halo-light) 42%, transparent);

    /* Nested, so it carries this rule's specificity (see fx/base.css). */
    @media (forced-colors: active) {
      --tw-shadow: revert-layer;
    }
  }
}
